using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class RecentProject {public string path,name,modified;public int pages;public bool missing;}
partial class Desktop {
 const string AppVersion="3.24.0";const string AppCreator="Sebastián Poberezny";
 string RecentFile{get{return args.Contains("--self-test")?Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"recent-selftest.json"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"LibroStudio","recent-projects.json");}}
 List<RecentProject> ReadRecents(){try{if(File.Exists(RecentFile))return json.Deserialize<List<RecentProject>>(File.ReadAllText(RecentFile))??new List<RecentProject>();}catch{}return new List<RecentProject>();}
 void RecordRecent(string path,string content){try{var root=json.Deserialize<Dictionary<string,object>>(content);string name=root.ContainsKey("title")?Convert.ToString(root["title"]):Path.GetFileNameWithoutExtension(path);var pages=root.ContainsKey("pages")?root["pages"] as System.Collections.ICollection:null;var recent=new RecentProject{path=Path.GetFullPath(path),name=name,modified=DateTime.UtcNow.ToString("o"),pages=pages==null?0:pages.Count};var list=ReadRecents().Where(r=>!string.Equals(r.path,recent.path,StringComparison.OrdinalIgnoreCase)).ToList();list.Insert(0,recent);Directory.CreateDirectory(Path.GetDirectoryName(RecentFile));File.WriteAllText(RecentFile,json.Serialize(list.Take(12).ToList()));}catch{}}
 object GetAppInfo(){var list=ReadRecents();foreach(var recent in list)recent.missing=!File.Exists(recent.path);return new{version=AppVersion,creator=AppCreator,recents=list,selftest=args.Contains("--self-test")};}
 object CheckRecents(){string a=Path.Combine(Path.GetTempPath(),"maquetario-recent-"+Guid.NewGuid()+".mqt"),b=Path.Combine(Path.GetTempPath(),"maquetario-recent-"+Guid.NewGuid()+".mqt");try{string content="{\"version\":3,\"title\":\"Prueba de recientes\",\"pages\":[{}]}";File.WriteAllText(a,content);File.WriteAllText(b,content);RecordRecent(a,content);RecordRecent(b,content);RecordRecent(a,content);var list=ReadRecents();if(list.Count!=2||list[0].path!=a||list[0].pages!=1)throw new Exception("Orden y persistencia de recientes");return new{ok=true,checks=new[]{"Recientes persisten en disco","Volver a abrir mueve el proyecto al principio","No se duplican entradas","Metadatos de proyecto conservados"}};}finally{if(File.Exists(a))File.Delete(a);if(File.Exists(b))File.Delete(b);if(File.Exists(RecentFile))File.Delete(RecentFile);}}
 void OpenRecent(string id,string path){var record=ReadRecents().FirstOrDefault(r=>string.Equals(r.path,path,StringComparison.OrdinalIgnoreCase));if(record==null)throw new Exception("El archivo no está en la lista de recientes.");if(!File.Exists(record.path))throw new Exception("El archivo se movió o ya no está disponible. Usá Abrir para buscarlo.");var file=new FileInfo(record.path);if(file.Length>80000000)throw new Exception("El proyecto supera 80 MB.");string content=File.ReadAllText(record.path);var root=json.Deserialize<Dictionary<string,object>>(content);if(!root.ContainsKey("version")||Convert.ToInt32(root["version"])!=3)throw new Exception("Proyecto incompatible.");projectPath=record.path;SetPackageFonts(projectPath);RecordRecent(record.path,content);Reply(id,new{content=content,path=record.path,packageFaces=packageFaces});}
}
